import numpy as np

# MECHANISM: Prioritize bins based on a combination of remaining capacity and a penalty for choosing bins with lower capacity, using a different penalty function and a different approach to combine the terms

def priority(item, bins):
    remaining_capacity = bins - item
    penalty = np.maximum(0, 1 - remaining_capacity / 150)
    return (remaining_capacity / item) * (1 - penalty)

