# MECHANISM: Use a weighted combination of remaining capacity and a penalty for choosing bins with lower capacity, using a modified logarithmic scale to penalize smaller bins more heavily.

import numpy as np

def priority(item, bins):
    remaining_capacity = bins - item
    penalty = np.maximum(0, 1 - remaining_capacity / 150)
    return remaining_capacity * np.log(remaining_capacity / (item + 1e-6)) * (1 - penalty ** 2)
